## 2. `pricing.test.ts`

```ts
import { describe, expect, it } from 'vitest';
import {
  allocateProportionally, divRoundHalfUp, priceCart, toStoreDate,
  type Cart, type Category, type LineItem, type PriceResult, type PromoDefinition,
} from './pricing';

let seq = 0;
const item = (unitPrice: number, qty: number, category: Category, name = `item-${++seq}`): LineItem =>
  ({ sku: name, name, unitPrice, qty, category });
const cart = (items: LineItem[], memberTier: Cart['memberTier'] = 'none'): Cart => ({ items, memberTier });
const kst = (ymd: string, hms = '12:00:00') => new Date(`${ymd}T${hms}+09:00`);
const withoutPromo = ({ promo: _ignored, ...rest }: PriceResult) => rest;

function expectConsistent(r: PriceResult) {
  const s = (f: (l: PriceResult['lines'][number]) => number) => r.lines.reduce((a, l) => a + f(l), 0);
  expect(r.subtotal).toBe(s((l) => l.grossAmount));
  expect(r.memberDiscount).toBe(s((l) => l.memberDiscount));
  expect(r.promoDiscount).toBe(s((l) => l.promoDiscount));
  expect(r.total).toBe(s((l) => l.netAmount));
  expect(r.total).toBe(r.subtotal - r.memberDiscount - r.promoDiscount);
  expect(r.vat).toBe(s((l) => l.vat));
  expect(r.taxableSupplyAmount + r.vat + r.exemptAmount).toBe(r.total);
  for (const l of r.lines) {
    for (const v of [l.grossAmount, l.memberDiscount, l.promoDiscount, l.netAmount, l.vat, l.supplyAmount]) {
      expect(Number.isInteger(v)).toBe(true);
    }
    expect(l.netAmount).toBeGreaterThanOrEqual(0);
    if (l.category === 'alcohol') expect([l.memberDiscount, l.promoDiscount]).toEqual([0, 0]);
    if (!l.taxable) expect(l.vat).toBe(0);
  }
}

describe('반올림 헬퍼', () => {
  it('half-up 방식이며 은행가 반올림이 아니다', () => {
    expect(divRoundHalfUp(29_850, 100)).toBe(299); // 298.5 → 299
    expect(divRoundHalfUp(5, 2)).toBe(3);          // 2.5 → 3
    expect(divRoundHalfUp(29_849, 100)).toBe(298);
    expect(divRoundHalfUp(0, 7)).toBe(0);
  });
});

describe('기본 계산 / 부가세', () => {
  it('부가세는 포함가에서 분리하고 total에 더하지 않으며, grocery는 면세다', () => {
    const r = priceCart(cart([item(10_000, 1, 'grocery'), item(11_000, 1, 'household')]));
    expect(r).toMatchObject({ total: 21_000, vat: 1_000, exemptAmount: 10_000, taxableSupplyAmount: 10_000 });
    expect(r.lines[0]).toMatchObject({ taxable: false, vat: 0 });
    expect(r.promo).toEqual({ status: 'none' });
    expectConsistent(r);
  });

  it.each([[1, 0], [5, 0], [6, 1], [16, 1], [17, 2], [8_075, 734], [11_990, 1_090]])(
    '과세 결제액 %i원의 부가세는 %i원 (10/110, half-up)',
    (net, vat) => {
      const r = priceCart(cart([item(net, 1, 'household')]));
      expect(r.lines[0].vat).toBe(vat);
      expect(r.lines[0].supplyAmount).toBe(net - vat);
    },
  );

  it.each([[1990.5, 1], [-1, 1], [1000, 1.5], [1000, -2]])('잘못된 단가/수량(%s, %s)은 거부한다', (p, q) => {
    expect(() => priceCart(cart([item(p, q, 'grocery')]))).toThrow(RangeError);
  });
});

describe('Plus 멤버십', () => {
  it('5%를 라인별로 half-up 반올림한다', () => {
    const r = priceCart(cart([item(1_990, 3, 'grocery'), item(6_490, 1, 'grocery'), item(1_999, 1, 'household')], 'plus'));
    expect(r.lines.map((l) => l.memberDiscount)).toEqual([299, 325, 100]); // 298.5, 324.5, 99.95
    expectConsistent(r);
  });

  it('주류는 멤버십 할인을 받지 않는다', () => {
    const r = priceCart(cart([item(11_990, 1, 'alcohol')], 'plus'));
    expect(r.lines[0]).toMatchObject({ memberDiscount: 0, netAmount: 11_990, vat: 1_090 });
  });
});

describe('프로모션 코드: 인식과 거절 사유', () => {
  it.each(['fresh10', 'FRESH10', 'Fresh10', '  fresh10 '])('"%s"를 대소문자·공백과 무관하게 인식한다', (code) => {
    const r = priceCart(cart([item(40_000, 1, 'grocery')]), code, kst('2025-07-02'));
    expect(r.promo).toEqual({ status: 'applied', code: 'FRESH10', discount: 4_000 });
    expect(r.total).toBe(36_000);
  });

  it.each(['', '   '])('빈 코드 "%s"는 코드 없음으로 처리한다', (code) => {
    expect(priceCart(cart([item(40_000, 1, 'grocery')]), code, kst('2025-07-02')).promo).toEqual({ status: 'none' });
  });

  it('unknown: 결제를 막지 않고 프로모션 없는 가격을 반환한다', () => {
    const c = cart([item(30_000, 1, 'grocery'), item(5_500, 1, 'household')], 'plus');
    const r = priceCart(c, 'free100', kst('2025-06-01'));
    expect(r.promo).toEqual({ status: 'rejected', code: 'FREE100', reason: 'unknown' });
    expect(withoutPromo(r)).toEqual(withoutPromo(priceCart(c, undefined, kst('2025-06-01'))));
  });

  describe('expired: 유효기간은 Asia/Seoul 날짜 기준이며 해당일을 포함한다', () => {
    const c = cart([item(30_000, 1, 'grocery')]);
    it('2025-06-30 23:59:59.999 KST(UTC 14:59:59.999)까지 유효하다', () => {
      expect(priceCart(c, 'SAVE5000', new Date('2025-06-30T14:59:59.999Z')).promo.status).toBe('applied');
    });
    it('2025-07-01 00:00 KST(UTC 06-30 15:00)부터 만료된다', () => {
      const r = priceCart(c, 'SAVE5000', new Date('2025-06-30T15:00:00Z'));
      expect(r.promo).toEqual({ status: 'rejected', code: 'SAVE5000', reason: 'expired' });
      expect(r.total).toBe(30_000);
      expect(toStoreDate(new Date('2025-06-30T15:00:00Z'))).toBe('2025-07-01');
    });
    it('FRESH10은 2025-12-31까지 유효하고 2026-01-01에 만료된다', () => {
      const big = cart([item(40_000, 1, 'grocery')]);
      expect(priceCart(big, 'FRESH10', kst('2025-12-31', '23:59:59')).promo.status).toBe('applied');
      expect(priceCart(big, 'FRESH10', kst('2026-01-01', '00:00:00')).promo).toMatchObject({ reason: 'expired' });
    });
  });

  describe('below_minimum: 주류를 제외하고 멤버십 할인 전 판매가로 판단한다', () => {
    it('주류를 포함하면 넘지만 제외하면 미달인 경우 거절한다', () => {
      const r = priceCart(cart([item(30_000, 1, 'grocery'), item(20_000, 1, 'alcohol')]), 'FRESH10', kst('2025-07-02'));
      expect(r.promo).toMatchObject({ status: 'rejected', reason: 'below_minimum' });
      expect(r.total).toBe(50_000);
    });
    it('경계값: 정확히 최소 금액이면 적용하고 1원 모자라면 거절한다', () => {
      expect(priceCart(cart([item(25_000, 1, 'grocery')]), 'SAVE5000', kst('2025-06-15')).total).toBe(20_000);
      expect(priceCart(cart([item(24_999, 1, 'grocery')]), 'SAVE5000', kst('2025-06-15')).promo)
        .toMatchObject({ reason: 'below_minimum' });
    });
    it('Plus 멤버는 할인 후 금액이 40,000원 미만이어도 판매가 40,000원이면 FRESH10을 적용받는다', () => {
      const r = priceCart(cart([item(40_000, 1, 'grocery')], 'plus'), 'FRESH10', kst('2025-07-02'));
      expect(r).toMatchObject({ memberDiscount: 2_000, promoDiscount: 3_800, total: 34_200 });
      const r2 = priceCart(cart([item(39_999, 1, 'grocery')], 'plus'), 'FRESH10', kst('2025-07-02'));
      expect(r2.promo).toMatchObject({ reason: 'below_minimum' });
    });
  });

  it('no_eligible_items: HOME15에 생활용품이 없거나 FRESH10에 주류만 있으면 거절한다', () => {
    expect(priceCart(cart([item(50_000, 1, 'grocery')]), 'HOME15', kst('2025-07-02')).promo)
      .toMatchObject({ reason: 'no_eligible_items' });
    expect(priceCart(cart([item(50_000, 1, 'alcohol')]), 'FRESH10', kst('2025-07-02')).promo)
      .toMatchObject({ reason: 'no_eligible_items' });
  });

  it('사유 우선순위: expired가 no_eligible_items보다 먼저다', () => {
    expect(priceCart(cart([item(50_000, 1, 'alcohol')]), 'SAVE5000', kst('2025-07-01')).promo)
      .toMatchObject({ reason: 'expired' });
  });
});

describe('정률 프로모션', () => {
  it('HOME15는 household에만 적용하고 637.5원을 638원으로 반올림한다', () => {
    const r = priceCart(
      cart([item(4_250, 1, 'household'), item(10_000, 1, 'grocery'), item(10_000, 1, 'alcohol')]),
      'home15', kst('2025-07-02'),
    );
    expect(r.lines.map((l) => l.promoDiscount)).toEqual([638, 0, 0]);
    expect(r.lines[0]).toMatchObject({ netAmount: 3_612, vat: 328 });
    expect(r.total).toBe(23_612);
    expectConsistent(r);
  });

  it('멤버십 할인 후 남은 금액에 적용한다 (4,250 → 4,037 → 15% = 605.55 → 606)', () => {
    const r = priceCart(
      cart([item(4_250, 1, 'household'), item(10_000, 1, 'grocery'), item(10_000, 1, 'alcohol')], 'plus'),
      'HOME15', kst('2025-07-02'),
    );
    expect(r.lines[0]).toMatchObject({ memberDiscount: 213, promoDiscount: 606, netAmount: 3_431 });
    expect(r.total).toBe(22_931);
    expectConsistent(r);
  });

  it('FRESH10은 주류 라인을 할인하지 않는다', () => {
    const r = priceCart(
      cart([item(30_000, 1, 'grocery'), item(10_000, 1, 'household'), item(50_000, 1, 'alcohol')]),
      'FRESH10', kst('2025-07-02'),
    );
    expect(r.lines.map((l) => l.promoDiscount)).toEqual([3_000, 1_000, 0]);
    expect(r).toMatchObject({ total: 86_000, vat: 818 + 4_545 });
    expectConsistent(r);
  });
});

describe('정액 프로모션 배분', () => {
  it('동률이면 잔액(-1원)을 앞 라인에 넣는다', () => {
    const r = priceCart(cart([item(10_000, 1, 'grocery'), item(10_000, 1, 'grocery'), item(10_000, 1, 'grocery')]),
      'SAVE5000', kst('2025-06-15'));
    expect(r.lines.map((l) => l.promoDiscount)).toEqual([1_666, 1_667, 1_667]);
    expect(r.total).toBe(25_000);
  });

  it('잔액(+1원)을 금액이 가장 큰 라인에 넣는다', () => {
    const r = priceCart(cart([item(10_000, 1, 'grocery'), item(10_000, 1, 'grocery'), item(10_500, 1, 'grocery')]),
      'SAVE5000', kst('2025-06-30'));
    expect(r.lines.map((l) => l.promoDiscount)).toEqual([1_639, 1_639, 1_722]);
    expectConsistent(r);
  });

